  fakeking: { cols: 16, rows: 4, idle: 0, walk: [1,2,3,4,5,6,7,8], cast: [9,10,11,12,13,14,15], footAdj: 0.9, top: [19,19,19,19], label: '뱀왕', scale: 1.5, radius: 1.0 }
